package com.klef.soa.docker.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Data Transfer Object for creating or updating a CommunityEvent.
 * Note: Does NOT include an ID field as the ID must be auto-generated by the database.
 * Student ID: 2400032700 | Name: UMMADI VIJAY KUMAR | Section: S51
 */
@Schema(description = "Request payload for creating/updating CommunityEvent. No ID field permitted.")
public class CommunityEventRequestDTO {

    @Schema(description = "Name or title of the community event", example = "Clean Energy & Climate Workshop")
    @NotBlank(message = "Event name is required and cannot be blank")
    @Size(min = 3, max = 100, message = "Event name must be between 3 and 100 characters")
    private String eventName;

    @Schema(description = "Location or venue where event is hosted", example = "Community Central Auditorium, Hall B")
    @NotBlank(message = "Venue is required and cannot be blank")
    @Size(min = 3, max = 150, message = "Venue must be between 3 and 150 characters")
    private String venue;

    @Schema(description = "Expected or confirmed number of attendees", example = "350")
    @NotNull(message = "Attendee count is required")
    @Min(value = 1, message = "Attendee count must be at least 1")
    @Max(value = 1000000, message = "Attendee count cannot exceed 1,000,000")
    private Integer attendeeCount;

    @Schema(description = "Whether the event has completed or is still upcoming", example = "false")
    @NotNull(message = "Completed status flag is required (true or false)")
    private Boolean completed;

    public CommunityEventRequestDTO() {
    }

    public CommunityEventRequestDTO(String eventName, String venue, Integer attendeeCount, Boolean completed) {
        this.eventName = eventName;
        this.venue = venue;
        this.attendeeCount = attendeeCount;
        this.completed = completed;
    }

    public String getEventName() {
        return eventName;
    }

    public void setEventName(String eventName) {
        this.eventName = eventName;
    }

    public String getVenue() {
        return venue;
    }

    public void setVenue(String venue) {
        this.venue = venue;
    }

    public Integer getAttendeeCount() {
        return attendeeCount;
    }

    public void setAttendeeCount(Integer attendeeCount) {
        this.attendeeCount = attendeeCount;
    }

    public Boolean getCompleted() {
        return completed;
    }

    public void setCompleted(Boolean completed) {
        this.completed = completed;
    }
}
